//! Creates the Python submodules that `heliox._core` exposes.
//!
//! Agents do not edit this file. Each submodule's `register` function calls
//! `new_submodule` to create its Python module.

use pyo3::prelude::*;

/// The dotted name of the extension module that all submodules belong to.
const PARENT_NAME: &str = "heliox._core";

/// Creates `heliox._core.<name>`, adds it to `parent` as the attribute `name`,
/// and registers it in `sys.modules`, so that `from heliox._core import <name>`
/// and `import heliox._core.<name>` both work.
pub fn new_submodule<'py>(
    parent: &Bound<'py, PyModule>,
    name: &str,
) -> PyResult<Bound<'py, PyModule>> {
    let py = parent.py();
    let full_name = format!("{PARENT_NAME}.{name}");
    let module = PyModule::new(py, &full_name)?;
    parent.add(name, &module)?;
    PyModule::import(py, "sys")?
        .getattr("modules")?
        .set_item(&full_name, &module)?;
    Ok(module)
}
